package pe.nexo.store.admin;import org.springframework.web.bind.annotation.*;import pe.nexo.store.order.*;import pe.nexo.store.product.*;import java.math.BigDecimal;import java.time.*;import java.time.format.TextStyle;import java.util.*;
@RestController@RequestMapping("/api/admin/dashboard")public class DashboardController{private final OrderRepository orders;private final ProductRepository products;public DashboardController(OrderRepository o,ProductRepository p){orders=o;products=p;}public record MonthSale(String month,BigDecimal total){}public record Recent(Long id,String orderNumber,String customerName,BigDecimal total,String status,LocalDateTime createdAt){}public record Stats(BigDecimal revenue,long orders,long customers,long lowStock,List<MonthSale>monthlySales,List<Recent>recentOrders){}@GetMapping public Stats stats(){List<CustomerOrder>all=orders.findAll();BigDecimal revenue=all.stream().filter(o->o.getStatus()!=OrderStatus.CANCELLED).map(CustomerOrder::getTotal).reduce(BigDecimal.ZERO,BigDecimal::add);long customers=all.stream().map(CustomerOrder::getEmail).distinct().count();long low=products.findAll().stream().filter(p->!p.isInStock()).count();YearMonth now=YearMonth.now();List<MonthSale>months=new ArrayList<>();for(int i=5;i>=0;i--){YearMonth t=now.minusMonths(i);BigDecimal total=all.stream().filter(o->o.getStatus()!=OrderStatus.CANCELLED&&YearMonth.from(o.getCreatedAt()).equals(t)).map(CustomerOrder::getTotal).reduce(BigDecimal.ZERO,BigDecimal::add);String label=t.getMonth().getDisplayName(TextStyle.SHORT,new Locale("es","PE"));months.add(new MonthSale(label.substring(0,1).toUpperCase()+label.substring(1),total));}List<Recent>recent=all.stream().sorted(Comparator.comparing(CustomerOrder::getCreatedAt).reversed()).limit(5).map(o->new Recent(o.getId(),o.getOrderNumber(),o.getCustomerName(),o.getTotal(),o.getStatus().name(),o.getCreatedAt())).toList();return new Stats(revenue,all.size(),customers,low,months,recent);}}
